callGraph.callee:
manager
                .list_names()
                .iter()
                .map(|name| {
                    let cfg = manager.get(name).unwrap();
                    serde_json::json!({
                        "name": name,
                        "active": *name == manager.active_target_name(),
                        "remote_host": cfg.remote_host,
                        "port": cfg.port,
                        "description": cfg.description,
                    })
                }).collect

inputs
                .iter()
                .filter_map(|s| {
                    let s = s.trim();
                    if s.is_empty() {
                        return None;
                    }
                    if let Some(pos) = s.find(':') {
                        let label = s[..pos].trim().to_string();
                        let path = s[pos + 1..].trim().to_string();
                        if label.is_empty() || path.is_empty() {
                            return None;
                        }
                        Some((label, path))
                    } else {
                        // No colon — treat whole string as path, derive label from filename
                        let p = std::path::Path::new(s);
                        let label = p
                            .file_stem()
                            .and_then(|l| l.to_str())
                            .unwrap_or(s)
                            .to_string();
                        Some((label, s.to_string()))
                    }
                }).collect

params
                .unwrap_or_default()
                .split(',')
                .filter(|s| !s.is_empty())
                .filter_map(|s| {
                    let (k, v) = s.split_once('=')?;
                    Some((k.to_string(), v.to_string()))
                }).collect

config
        .corners
        .iter()
        .map(|c| {
            let _name = escape_skill_string(&c.name);
            let section = escape_skill_string(&c.section);
            // Collect extra vars
            let vars: Vec<String> = c
                .vars
                .iter()
                .map(|(k, v)| {
                    let val = match v {
                        serde_json::Value::Number(n) => n.to_string(),
                        serde_json::Value::String(s) => format!("\"{s}\""),
                        other => other.to_string(),
                    };
                    format!("    desVar(\"{k}\" {val})")
                })
                .collect();
            let vars_code = vars.join("\n");
            format!(
                r#"    ;; Corner: {name}
    modelFile('("{model_file}" "") "{section}")
    temp({temp})
{vars_code}"#,
                name = c.name,
                temp = c.temp,
            )
        }).collect

c
                .vars
                .iter()
                .map(|(k, v)| {
                    let val = match v {
                        serde_json::Value::Number(n) => n.to_string(),
                        serde_json::Value::String(s) => format!("\"{s}\""),
                        other => other.to_string(),
                    };
                    format!("    desVar(\"{k}\" {val})")
                }).collect

corner
            .vars
            .iter()
            .map(|(k, v)| {
                let val = match v {
                    serde_json::Value::Number(n) => n.to_string(),
                    serde_json::Value::String(s) => format!("\"{s}\""),
